package utils;

import io.github.cdimascio.dotenv.Dotenv;

public class ConfigReader {

    private static final Dotenv dotenv = Dotenv.configure()
            .ignoreIfMissing()
            .load();

    public static String get(String key) {
        String value = System.getenv(key);
        if (value == null || value.isEmpty()) {
            value = dotenv.get(key);
        }
        return value;
    }

    public static String getAppUrl() {
        return get("APP_URL");
    }

    public static String getUserEmail() {
        return get("USER_EMAIL");
    }

    public static String getUserPassword() {
        return get("USER_PASSWORD");
    }

    public static boolean isHeadless() {
        return Boolean.parseBoolean(get("HEADLESS") != null ? get("HEADLESS") : "true");
    }
}
```

#### `src/main/java/utils/DriverFactory.java`
```java
package utils;

import com.microsoft.playwright.*;

import java.nio.file.Paths;

public class DriverFactory {

    private static final ThreadLocal<Playwright> playwrightThread = new ThreadLocal<>();
    private static final ThreadLocal<Browser> browserThread = new ThreadLocal<>();
    private static final ThreadLocal<BrowserContext> contextThread = new ThreadLocal<>();
    private static final ThreadLocal<Page> pageThread = new ThreadLocal<>();

    public static Page initDriver() {
        Playwright playwright = Playwright.create();
        playwrightThread.set(playwright);

        boolean headless = ConfigReader.isHeadless();
        String browserType = ConfigReader.get("BROWSER");
        if (browserType == null) browserType = "chromium";

        Browser browser;
        switch (browserType.toLowerCase()) {
            case "firefox":
                browser = playwright.firefox().launch(new BrowserType.LaunchOptions().setHeadless(headless));
                break;
            case "webkit":
                browser = playwright.webkit().launch(new BrowserType.LaunchOptions().setHeadless(headless));
                break;
            default:
                browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(headless));
                break;
        }
        browserThread.set(browser);

        BrowserContext context = browser.newContext(new Browser.NewContextOptions()
                .setRecordVideoDir(Paths.get("traces/videos/")));

        context.tracing().start(new Tracing.StartOptions()
                .setScreenshots(true)
                .setSnapshots(true)
                .setSources(true));

        contextThread.set(context);

        Page page = context.newPage();
        pageThread.set(page);

        return page;
    }

    public static Page getPage() {
        return pageThread.get();
    }

    public static BrowserContext getContext() {
        return contextThread.get();
    }

    public static void quitDriver() {
        if (contextThread.get() != null) {
            contextThread.get().tracing().stop(new Tracing.StopOptions()
                    .setPath(Paths.get("traces/trace.zip")));
            contextThread.get().close();
        }
        if (browserThread.get() != null) {
            browserThread.get().close();
        }
        if (playwrightThread.get() != null) {
            playwrightThread.get().close();
        }
        pageThread.remove();
        contextThread.remove();
        browserThread.remove();
        playwrightThread.remove();
    }
}
```

#### `src/main/java/pages/BasePage.java`
```java
package pages;

import com.microsoft.playwright.Page;
import com.microsoft.playwright.options.WaitForSelectorState;

public abstract class BasePage {

    protected Page page;

    public BasePage(Page page) {
        this.page = page;
    }

    protected void navigateTo(String url) {
        page.navigate(url);
    }

    protected void click(String selector) {
        page.waitForSelector(selector, new Page.WaitForSelectorOptions().setState(WaitForSelectorState.VISIBLE));
        page.click(selector);
    }

    protected void fill(String selector, String text) {
        page.waitForSelector(selector, new Page.WaitForSelectorOptions().setState(WaitForSelectorState.VISIBLE));
        page.fill(selector, text);
    }

    protected String getText(String selector) {
        page.waitForSelector(selector, new Page.WaitForSelectorOptions().setState(WaitForSelectorState.VISIBLE));
        return page.textContent(selector).trim();
    }

    protected boolean isElementVisible(String selector) {
        try {
            return page.isVisible(selector);
        } catch (Exception e) {
            return false;
        }
    }

    protected void selectOptionByText(String selector, String text) {
        page.selectOption(selector, text);
    }
}
```

