#### 1. `src/main/java/utils/DriverManager.java`
```java
package utils;

import com.microsoft.playwright.*;

import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class DriverManager {

    private static Playwright playwright;
    private static Browser browser;
    private static final ThreadLocal<BrowserContext> contextTL = new ThreadLocal<>();
    private static final ThreadLocal<Page> pageTL = new ThreadLocal<>();

    public static final Path AUTH_STATE_PATH = Paths.get("playwright/.auth/user.json");

    public static synchronized void initDriver() {
        if (playwright == null) {
            playwright = Playwright.create();
            String browserTypeStr = ConfigReader.get("BROWSER", "chromium").toLowerCase();
            boolean headless = Boolean.parseBoolean(ConfigReader.get("HEADLESS", "true"));
            double slowMo = Double.parseDouble(ConfigReader.get("SLOW_MO", "0"));

            BrowserType browserType;
            switch (browserTypeStr) {
                case "firefox":
                    browserType = playwright.firefox();
                    break;
                case "webkit":
                    browserType = playwright.webkit();
                    break;
                default:
                    browserType = playwright.chromium();
                    break;
            }

            browser = browserType.launch(new BrowserType.LaunchOptions()
                    .setHeadless(headless)
                    .setSlowMo(slowMo));

            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                if (browser != null) {
                    browser.close();
                }
                if (playwright != null) {
                    playwright.close();
                }
            }));
        }

        Browser.NewContextOptions contextOptions = new Browser.NewContextOptions()
                .setViewportSize(1920, 1080)
                .setRecordVideoDir(Paths.get("traces/videos/"));

        File authFile = AUTH_STATE_PATH.toFile();
        if (authFile.exists() && authFile.length() > 0) {
            contextOptions.setStorageStatePath(AUTH_STATE_PATH);
        }

        BrowserContext context = browser.newContext(contextOptions);
        contextTL.set(context);

        context.tracing().start(new Tracing.StartOptions()
                .setScreenshots(true)
                .setSnapshots(true)
                .setSources(true));

        Page page = context.newPage();
        pageTL.set(page);
    }

    public static Page getPage() {
        return pageTL.get();
    }

    public static BrowserContext getContext() {
        return contextTL.get();
    }

    public static void quitDriver(String scenarioName) {
        if (getContext() != null) {
            try {
                getContext().tracing().stop(new Tracing.StopOptions()
                        .setPath(Paths.get("traces/" + scenarioName + "-trace.zip")));
            } catch (Exception ignored) {
            }
            getContext().close();
        }
        pageTL.remove();
        contextTL.remove();
    }
}
```

