package pages;

import com.microsoft.playwright.BrowserContext;
import com.microsoft.playwright.Page;
import utils.DriverManager;

import java.io.File;

public class LoginPage extends BasePage {

    private final String emailInput = "input[name='email'], input[type='email'], #email";
    private final String passwordInput = "input[name='password'], input[type='password'], #password";
    private final String loginBtn = "button[type='submit'], button:has-text('Log In'), button:has-text('LOGIN')";

    public LoginPage(Page page) {
        super(page);
    }

    public void navigateTo(String baseUrl) {
        page.navigate(baseUrl);
    }

    public boolean isLoggedIn() {
        try {
            return !page.locator(emailInput).isVisible();
        } catch (Exception e) {
            return false;
        }
    }

    public void login(String email, String password) {
        if (page.locator(emailInput).isVisible()) {
            page.fill(emailInput, email);
            page.fill(passwordInput, password);
            page.click(loginBtn);
            page.waitForLoadState();
            saveStorageState();
        }
    }

    public void saveStorageState() {
        try {
            File authDir = DriverManager.AUTH_STATE_PATH.getParent().toFile();
            if (!authDir.exists()) {
                authDir.mkdirs();
            }
            page.context().storageState(new BrowserContext.StorageStateOptions()
                    .setPath(DriverManager.AUTH_STATE_PATH));
        } catch (Exception e) {
            System.err.println("Failed to save storage state: " + e.getMessage());
        }
    }
}
