package stepdefinitions;

import io.cucumber.java.en.*;
import org.junit.jupiter.api.Assertions;
import pages.LoginPage;
import pages.NavigationHeaderPage;
import pages.RequestAuthorizationPage;
import utils.ConfigReader;
import utils.DriverManager;

public class RequestAuthorizationSteps {

    private LoginPage loginPage;
    private NavigationHeaderPage navPage;
    private RequestAuthorizationPage reqPage;

    @Given("User is logged into the Insula portal")
    public void userIsLoggedIntoPortal() {
        loginPage = new LoginPage(DriverManager.getPage());
        loginPage.navigateTo(ConfigReader.get("BASE_URL"));
        if (!loginPage.isLoggedIn()) {
            loginPage.login(ConfigReader.get("USER_EMAIL"), ConfigReader.get("USER_PASSWORD"));
        }
    }

    @When("User navigates to {string} page")
    public void userNavigatesToPage(String menuOption) {
        navPage = new NavigationHeaderPage(DriverManager.getPage());
        if (menuOption.equalsIgnoreCase("Request Credit Authorization")) {
            navPage.clickRequestCreditAuthorization();
        } else if (menuOption.equalsIgnoreCase("View Credit/Background Requests")) {
            navPage.clickViewCreditBackgroundRequests();
        }
    }

    @When("User selects request type {string}")
    public void userSelectsRequestType(String type) {
        reqPage = new RequestAuthorizationPage(DriverManager.getPage());
        reqPage.selectRequestType(type);
    }

    @When("User selects borrower type {string}")
    public void userSelectsBorrowerType(String type) {
        reqPage.selectBorrowerType(type);
    }

    @When("User enters borrower first name {string}, last name {string}, email {string}")
    public void userEntersBorrowerDetails(String fname, String lname, String email) {
