    @Then("Success modal should be displayed with text {string}")
    public void successModalShouldBeDisplayed(String expectedMessage) {
        Assertions.assertTrue(reqPage.isSuccessModalDisplayed(), "Success modal should be visible");
        Assertions.assertTrue(reqPage.getSuccessModalMessageText().contains(expectedMessage), "Message text mismatch");
        reqPage.dismissSuccessModal();
    }

    @Then("Success modal should NOT be displayed")
    public void successModalShouldNotBeDisplayed() {
        Assertions.assertFalse(reqPage.isSuccessModalDisplayed(), "Success modal should NOT be visible");
    }

