    public void requestAuthHeaderDisplayed() {
        reqPage = new RequestAuthorizationPage(DriverManager.getPage());
        Assertions.assertTrue(reqPage.isPageHeaderDisplayed());
    }

    @Then("Type selection prompt should be visible")
    public void typePromptVisible() {
        Assertions.assertTrue(reqPage.isTypePromptDisplayed());
    }

    @Then("Borrower selection prompt should be visible")
    public void borrowerPromptVisible() {
        Assertions.assertTrue(reqPage.isBorrowerPromptDisplayed());
    }
