import { Before, After, BeforeAll, AfterAll, Status } from '@cucumber/cucumber';
import { ChromiumBrowser, chromium, BrowserContext, Page } from '@playwright/test';
import path from 'path';

let browser: ChromiumBrowser;
let context: BrowserContext;

BeforeAll(async function () {
  browser = await chromium.launch({ headless: true });
});

AfterAll(async function () {
  await browser.close();
});

Before(async function () {
  const authPath = path.join(__dirname, '../playwright/.auth/user.json');
  try {
    context = await browser.newContext({ storageState: authPath });
  } catch (e) {
    context = await browser.newContext();
  }
  this.page = await context.newPage();
});

After(async function (scenario) {
  if (scenario.result?.status === Status.FAILED) {
    const screenshot = await (this.page as Page).screenshot({ type: 'png' });
    this.attach(screenshot, 'image/png');
  }
  await (this.page as Page).close();
  await context.close();
});
