package pages;

import com.microsoft.playwright.Page;
import com.microsoft.playwright.options.WaitForSelectorState;

public abstract class BasePage {
    protected Page page;

    public BasePage(Page page) {
        this.page = page;
    }

    protected void navigateTo(String url) {
        // page.setDefaultNavigationTimeout(60000);
        page.navigate(url);
    }

    protected void click(String selector) {
        page.waitForSelector(selector, new Page.WaitForSelectorOptions().setState(WaitForSelectorState.VISIBLE));
        page.click(selector);
    }

    protected void fill(String selector, String value) {
        page.waitForSelector(selector, new Page.WaitForSelectorOptions().setState(WaitForSelectorState.VISIBLE));
        page.fill(selector, value);
    }

    protected String getText(String selector) {
        page.waitForSelector(selector, new Page.WaitForSelectorOptions().setState(WaitForSelectorState.VISIBLE));
        return page.textContent(selector).trim();

    }

    protected boolean isVisible(String selector) {
        try {
            return page.isVisible(selector);
        } catch (Exception e) {
            return false;
        }
    }

    protected void scrollIntoViewIfNeeded(String selector) {
        page.locator(selector).scrollIntoViewIfNeeded();
    }


    protected void mouseHover(String selector){
        page.waitForSelector(selector, new Page.WaitForSelectorOptions().setState(WaitForSelectorState.VISIBLE));
        page.hover(selector);
    }

    protected void waitForSeconds(int seconds) {
    page.waitForTimeout(seconds * 1000);
}

protected void waitForElement(String selector) {
    page.waitForSelector(selector,
            new Page.WaitForSelectorOptions()
                    .setState(WaitForSelectorState.VISIBLE));
}



}
