package pages;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import io.qameta.allure.Allure;
import io.qameta.allure.Step;

import java.io.ByteArrayInputStream;

public class BasePage {
    public Page page;

    public BasePage(Page page) {
        this.page = page;
    }

    @Step("Click on target element")
    public void clickElement(Locator locator) {
        locator.click();
    }

    @Step("Fill input with value: '{1}'")
    public void fillInput(Locator locator, String value) {
        if (value != null && !value.isEmpty()) {
            locator.fill(value);
        }
    }

    @Step("Verify element contains text: '{1}'")
    public void verifyElementContainsText(Locator locator, String expectedText) {
        locator.waitFor();
        String actualText = locator.textContent();
        if (actualText == null || !actualText.contains(expectedText)) {
            attachScreenshot("Verification Failure Screenshot");
            throw new AssertionError("Expected text '" + expectedText + "' not found in element. Actual text: '" + actualText + "'");
        }
    }

    public void attachScreenshot(String attachmentName) {
        try {
            byte[] screenshot = page.screenshot(new Page.ScreenshotOptions().setFullPage(true));
            Allure.addAttachment(attachmentName, new ByteArrayInputStream(screenshot));
        } catch (Exception e) {
            System.err.println("Failed to capture screenshot for Allure report: " + e.getMessage());
        }
    }
}
