package pages;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import io.qameta.allure.Step;

public class LoanFlowPage extends BasePage {
    public Locator loansMenu;
    public Locator quoteAndSubmitOption;
    public Locator amcVendorSelect;
    public Locator borrowerNameInput;
    public Locator loanAmountInput;
    public Locator submitLoanBtn;
    public Locator confirmationMessage;
    public Locator pageHeader;
    public Locator proceedSummaryBtn;

    public LoanFlowPage(Page page) {
        super(page);
        this.loansMenu = page.locator("text=LOANS");
        this.quoteAndSubmitOption = page.locator("text=Quote & Submit Loans");
        this.amcVendorSelect = page.locator("select[name='amcVendor']");
        this.borrowerNameInput = page.locator("input[name='borrowerName']");
        this.loanAmountInput = page.locator("input[name='loanAmount']");
        this.submitLoanBtn = page.locator("button:has-text('SAVE & SUBMIT AS LOAN')");
        this.confirmationMessage = page.locator(".confirmation-message");
        this.pageHeader = page.locator("h1.page-title");
        this.proceedSummaryBtn = page.locator("button:has-text('CONTINUE'), button:has-text('NEXT'), button:has-text('PROCEED TO SUBMISSION')").first();
    }

    @Step("Navigate to Quote & Submit Loans screen")
    public void navigateToQuoteAndSubmit() {
        loansMenu.hover();
        clickElement(quoteAndSubmitOption);
    }

    @Step("Select AMC Vendor: {0}")
    public void selectAmcVendor(String amcName) {
        amcVendorSelect.selectOption(amcName);
    }

    @Step("Fill initial loan application details for borrower '{0}' with amount '${1}'")
    public void fillLoanApplicationDetails(String borrowerName, String loanAmount) {
        fillInput(borrowerNameInput, borrowerName);
        fillInput(loanAmountInput, loanAmount);
    }

    @Step("Submit initial loan application")
    public void submitLoan() {
        clickElement(submitLoanBtn);
    }

    @Step("Verify submission confirmation message: {0}")
    public void verifySubmissionConfirmation(String expectedMessage) {
        verifyElementContainsText(confirmationMessage, expectedMessage);
    }

    @Step("Execute Private Lender Flow: {0}")
    public void executePrivateLenderFlow(String flowType) {
        loansMenu.hover();
        page.locator("text=" + flowType).click();
    }

    @Step("Verify page flow header: {0}")
    public void verifyFlowHeader(String expectedHeader) {
        verifyElementContainsText(pageHeader, expectedHeader);
    }

    @Step("Proceed from Loan Summary screen to submission workflow")
    public void proceedFromLoanSummary() {
        clickElement(proceedSummaryBtn);
    }
}
