```java
package hooks;

import com.microsoft.playwright.*;
import io.cucumber.java.After;
import io.cucumber.java.Before;
import io.cucumber.java.Scenario;
import utils.ConfigReader;

import java.nio.file.Paths;
import java.util.UUID;

public class Hooks {

    private static Playwright playwright;
    private static Browser browser;
    private BrowserContext context;
    private Page page;

    @Before
    public void setUp() {
        playwright = Playwright.create();
        boolean headless = Boolean.parseBoolean(ConfigReader.get("HEADLESS"));

        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(headless));

        context = browser.newContext(new Browser.NewContextOptions()
                .setRecordVideoDir(Paths.get("traces/videos/"))
                .setRecordVideoSize(1280, 720));

        context.tracing().start(new Tracing.StartOptions()
                .setScreenshots(true)
                .setSnapshots(true)
                .setSources(true));

        page = context.newPage();
    }

    public Page getPage() {
        return page;
    }

    @After
    public void tearDown(Scenario scenario) {
        String testId = UUID.randomUUID().toString().substring(0, 8);

        byte[] screenshot = page.screenshot(new Page.ScreenshotOptions().setFullPage(true));
        scenario.attach(screenshot, "image/png", "Scenario-Screenshot-" + testId);

        page.screenshot(new Page.ScreenshotOptions()
                .setPath(Paths.get("traces/screenshots/" + scenario.getName().replaceAll("[^a-zA-Z0-9]", "_") + "-" + testId + ".png"))
                .setFullPage(true));

        context.tracing().stop(new Tracing.StopOptions()
                .setPath(Paths.get("traces/trace-" + scenario.getName().replaceAll("[^a-zA-Z0-9]", "_") + "-" + testId + ".zip")));

        context.close();
        browser.close();
        playwright.close();
    }
}
```

