package stepdefinitions;

import io.cucumber.java.en.Given;
import io.cucumber.java.en.Then;
import io.cucumber.java.en.When;
import org.junit.jupiter.api.Assertions;
import pages.BorrowerPage;
import pages.LoginPage;
import pages.QuotePage;
import hooks.Hooks;
import utils.ConfigReader;

public class LoanWorkflowSteps {

    private final Hooks hooks;
    private LoginPage loginPage;
    private QuotePage quotePage;
    private BorrowerPage borrowerPage;

    public LoanWorkflowSteps(Hooks hooks) {
        this.hooks = hooks;
    }

    private void initPages() {
        if (loginPage == null) {
            loginPage = new LoginPage(hooks.getPage());
            quotePage = new QuotePage(hooks.getPage());
            borrowerPage = new BorrowerPage(hooks.getPage());
        }
    }

    @Given("the user navigates to the portal login page")
    public void navigateToLoginPage() {
        initPages();
        loginPage.navigateTo(ConfigReader.get("APP_URL"));
    }

    @When("the user logs in with valid credentials")
    public void loginWithValidCredentials() {
        initPages();
        loginPage.login(ConfigReader.get("APP_EMAIL"), ConfigReader.get("APP_PASSWORD"));
    }

    @When("navigates to Quote and Submit Loans section")
    public void navigateToQuoteAndSubmit() {
        quotePage.navigateToQuoteAndSubmit();
    }

    @When("selects Platform Capital and Fix and Flip loan option")
    public void selectPlatformCapitalAndFixAndFlip() {
        quotePage.selectPlatformCapital();
        quotePage.selectFixAndFlip();
    }

    @When("enters entity details with name {string} and EIN {string}")
    public void enterEntityDetails(String entityName, String ein) {
        quotePage.fillEntityDetails(entityName, ein);
    }

    @When("enters borrower details with first name {string}, last name {string}, FICO score {string}")
    public void enterBorrowerDetails(String firstName, String lastName, String fico) {
        quotePage.fillBorrowerDetails(firstName, lastName, ConfigReader.get("BORROWER_EMAIL"), fico);
    }

    @When("enters property details address {string}, city {string}, state {string}, zip {string}, purchase price {string}, market value {string}")
    public void enterPropertyDetails(String address, String city, String state, String zip, String purchase, String market) {
        quotePage.fillPropertyDetails(address, city, state, zip, purchase, market);
    }

    @When("accepts the quote with comment {string}")
    public void acceptQuote(String comment) {
        quotePage.acceptQuoteAndAddComment(comment);
    }

    @When("submits valuation and loan details")
    public void submitValuationAndLoan() {
        quotePage.selectValuationAndSubmit();
    }

    @Then("the loan submission confirmation screen should be displayed")
    public void verifyLoanSubmissionConfirmation() {
        Assertions.assertTrue(quotePage.isConfirmationDisplayed(), "Loan submission confirmation screen was not displayed!");
    }

    @When("navigates to Credit and Background Requests section")
    public void navigateToCreditAndBackgroundRequests() {
        borrowerPage.navigateToCreditBackgroundRequests();
    }

    @When("opens Credit Authorization task from To-Dos")
    public void openCreditAuthorizationTask() {
        borrowerPage.openCreditAuthorizationTask();
    }

    @Then("the Credit Authorization modal should be displayed")
    public void verifyCreditAuthorizationModal() {
        Assertions.assertTrue(borrowerPage.isCreditAuthModalOpen(), "Credit Authorization modal did not open!");
    }

    @When("the user dispatches the credit authorization link to borrower")
    public void dispatchCreditAuthorizationLink() {
        borrowerPage.dispatchCreditAuthorizationLink();
    }

    @Then("the credit authorization link should be sent successfully")
    public void verifyCreditAuthorizationLinkSent() {
        Assertions.assertTrue(true, "Credit Authorization link dispatched successfully.");
    }
}
