package pages;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;

import java.util.List;

public class ProgressTrackerPage extends BasePage {

    private final Locator trackerSteps = page.locator(".progress-tracker .step-item");
    private final Locator activeStepIndicator = page.locator(".progress-tracker .step-item.active");
    private final Locator activeStepUnderline = page.locator(".progress-tracker .step-item.active .blue-underline");

    public ProgressTrackerPage(Page page) {
        super(page);
    }

    public int getStepCount() {
        return trackerSteps.count();
    }

    public List<String> getAllStepTitles() {
        return trackerSteps.allTextContents();
    }

    public String getActiveStepText() {
        return activeStepIndicator.textContent().trim();
    }

    public boolean isActiveStepUnderlinedBlue() {
        if (!activeStepUnderline.isVisible()) {
            return false;
        }
        String borderBottomColor = activeStepUnderline.evaluate("el => getComputedStyle(el).borderBottomColor").toString();
        return borderBottomColor.contains("rgb(0, 102, 255)") || borderBottomColor.contains("rgb(0, 85, 204)") || borderBottomColor.contains("rgb(0, 0, 255)");
    }

    public boolean isStepActive(int stepIndexOneBased) {
        Locator step = trackerSteps.nth(stepIndexOneBased - 1);
        return step.getAttribute("class").contains("active");
    }

    public boolean isStepDisabled(int stepIndexOneBased) {
        Locator step = trackerSteps.nth(stepIndexOneBased - 1);
        String classes = step.getAttribute("class");
        String ariaDisabled = step.getAttribute("aria-disabled");
        return classes.contains("disabled") || "true".equalsIgnoreCase(ariaDisabled);
    }

    public void clickStep(int stepIndexOneBased) {
        trackerSteps.nth(stepIndexOneBased - 1).click();
    }

    public String getStepPointerEventsStyle(int stepIndexOneBased) {
        return trackerSteps.nth(stepIndexOneBased - 1).evaluate("el => getComputedStyle(el).pointerEvents").toString();
    }
}
