package tests;

import com.microsoft.playwright.*;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.TestInfo;
import utils.ConfigReader;

import java.nio.file.Paths;
import java.util.UUID;

public class BaseTest {
    protected Playwright playwright;
    protected Browser browser;
    protected BrowserContext context;
    protected Page page;

    @BeforeEach
    public void setUp(TestInfo testInfo) {
        playwright = Playwright.create();
        String browserType = ConfigReader.getProperty("BROWSER", "chromium");
        boolean headless = Boolean.parseBoolean(ConfigReader.getProperty("HEADLESS", "true"));

        BrowserType.LaunchOptions launchOptions = new BrowserType.LaunchOptions().setHeadless(headless);

        switch (browserType.toLowerCase()) {
            case "firefox":
                browser = playwright.firefox().launch(launchOptions);
                break;
            case "webkit":
                browser = playwright.webkit().launch(launchOptions);
                break;
            default:
                browser = playwright.chromium().launch(launchOptions);
                break;
        }

        context = browser.newContext(new Browser.NewContextOptions()
                .setRecordVideoDir(Paths.get("traces/videos/")));

        context.tracing().start(new Tracing.StartOptions()
                .setScreenshots(true)
                .setSnapshots(true)
                .setSources(true));

        page = context.newPage();
        String baseUrl = ConfigReader.getProperty("APP_URL", "https://app.fixandflipquote.com/wizard");
        page.navigate(baseUrl);
    }

    @AfterEach
    public void tearDown(TestInfo testInfo) {
        String testName = testInfo.getDisplayName().replaceAll("[^a-zA-Z0-9.-]", "_");

        page.screenshot(new Page.ScreenshotOptions()
                .setPath(Paths.get("traces/screenshots/" + testName + ".png"))
                .setFullPage(true));

        context.tracing().stop(new Tracing.StopOptions()
                .setPath(Paths.get("traces/trace_" + testName + "_" + UUID.randomUUID().toString().substring(0, 5) + ".zip")));

        if (context != null) context.close();
        if (browser != null) browser.close();
        if (playwright != null) playwright.close();
    }
}
